class Solution {
    public List<String> commonChars(String[] words){
        int[] minimum=new int[26];
        Arrays.fill(minimum,Integer.MAX_VALUE);
        for(String word:words){
            int[] frequency=new int[26];
            for(char ch:word.toCharArray())frequency[ch-'a']++;
            for(int i=0;i<26;i++)minimum[i]=Math.min(minimum[i],frequency[i]);
        }
        List<String> answer=new ArrayList<>();
        for(int i=0;i<26;i++)for(int count=0;count<minimum[i];count++)answer.add(String.valueOf((char)('a'+i)));
        return answer;
    }
}

code.kotlin:
class Solution {
    fun commonChars(words:Array<String>):List<String>{
        val minimum=IntArray(26){
            Int.MAX_VALUE
        };
        for(word in words){
            val frequency=IntArray(26);
            for(ch in word)frequency[ch-'a']++;
            for(i in 0..25)minimum[i]=minOf(minimum[i],frequency[i])
        };
        val answer=mutableListOf<String>();
        for(i in 0..25)repeat(minimum[i]){
            answer.add(('a'.code+i).toChar().toString())
        };
        return answer
    }
}

