class Solution {
    public: vector<string> commonChars(vector<string>& words){
        vector<int> minimum(26,INT_MAX);
        for(string& word:words){
            vector<int> frequency(26);
            for(char ch:word)++frequency[ch-'a'];
            for(int i=0;i<26;++i)minimum[i]=min(minimum[i],frequency[i]);
        }
        vector<string> answer;
        for(int i=0;i<26;++i)for(int count=0;count<minimum[i];++count)answer.push_back(string(1,'a'+i));
        return answer;
    }
};
